// Shared printable letterhead — lightning logo on the left, company name +
// address + TIN in the middle, optional document-type label on the right.
// Used by Voucher, Delivery Receipt, and Transmittal printables. The
// Purchase Order / Purchase Request use DocPrintHeader (also letterhead-style
// but with a right-side meta block instead of a label chip).
function SteezeLetterhead({ docTitle }){
  return (
    <div className="flex items-stretch border-2 border-slate-900 mb-4">
      <div className="flex items-center justify-center px-5 border-r-2 border-slate-900 bg-white">
        <SteezeBolt className="w-14 h-14" fill="#203A5D" />
      </div>
      <div className="flex-1 px-4 py-2.5 flex items-center justify-between gap-4">
        <div>
          <div className="text-xl font-extrabold tracking-wide text-slate-900">STEEZE CORPORATION</div>
          <div className="text-[10px] text-slate-600 leading-snug">{STEEZE_ADDRESS}</div>
          <div className="text-[10px] text-slate-600">TIN: {STEEZE_TIN}</div>
        </div>
        {docTitle && (
          <div className="text-right">
            <div className="inline-block px-4 py-1 bg-slate-800 text-white text-sm font-bold tracking-widest">{docTitle}</div>
          </div>
        )}
      </div>
    </div>
  );
}

// On-screen error reporter so problems show as readable text, not a blank page.
function showFatal(msg){
  var d=document.getElementById('fatal');
  if(!d){ d=document.createElement('div'); d.id='fatal';
    d.style.cssText='position:fixed;bottom:0;left:0;right:0;max-height:40vh;overflow:auto;background:#fee2e2;color:#991b1b;font:12px/1.4 monospace;padding:12px;z-index:99999;white-space:pre-wrap;border-top:2px solid #991b1b;';
    document.body.appendChild(d); }
  d.textContent='⚠ ERROR (screenshot this and send it):\n\n'+msg;
}
window.addEventListener('error', e => showFatal(e.message || String(e)));
window.addEventListener('unhandledrejection', e => showFatal((e.reason && (e.reason.message||e.reason.error_description)) || JSON.stringify(e.reason) || 'Unknown promise rejection'));

