    trims:{ enabled:false, columns:[{title:'WOVEN SIZE LABEL',name:'',image:''},{title:'YKK ZIPPER',name:'',image:''},{title:'BUTTONS',name:'',image:''}], packaging:{title:'PACKAGING',type:'REGULAR PLASTIC',size:''} },
    graphicFront:{ enabled:false, artworkImage:'', placementImage:'', widthLabel:'', cw1:{technique:'',position:'',size:'',extra:''}, cw2:{technique:'',position:'',size:'',extra:''} },
    graphicBack:{ enabled:false, artworkImage:'', placementImage:'', widthLabel:'', cw1:{technique:'',position:'',size:'',extra:''}, cw2:{technique:'',position:'',size:'',extra:''} },
    bom:{ enabled:false, rows:[] },
